type UnescapedCookieParamError struct {
	ParamName string
	Err       error
}

func (e *UnescapedCookieParamError) Error() string {
	return fmt.Sprintf("error unescaping cookie parameter '%s'", e.ParamName)
}

func (e *UnescapedCookieParamError) Unwrap() error {
	return e.Err
}

type UnmarshalingParamError struct {
	ParamName string
	Err       error
}

func (e *UnmarshalingParamError) Error() string {
	return fmt.Sprintf("Error unmarshaling parameter %s as JSON: %s", e.ParamName, e.Err.Error())
}

func (e *UnmarshalingParamError) Unwrap() error {
	return e.Err
}

type RequiredParamError struct {
	ParamName string
}

func (e *RequiredParamError) Error() string {
	return fmt.Sprintf("Query argument %s is required, but not found", e.ParamName)
}

type RequiredHeaderError struct {
	ParamName string
	Err       error
}

func (e *RequiredHeaderError) Error() string {
	return fmt.Sprintf("Header parameter %s is required, but not found", e.ParamName)
}

func (e *RequiredHeaderError) Unwrap() error {
	return e.Err
}

type InvalidParamFormatError struct {
	ParamName string
	Err       error
}

func (e *InvalidParamFormatError) Error() string {
	return fmt.Sprintf("Invalid format for parameter %s: %s", e.ParamName, e.Err.Error())
}

func (e *InvalidParamFormatError) Unwrap() error {
	return e.Err
}

type TooManyValuesForParamError struct {
	ParamName string
	Count     int
}

func (e *TooManyValuesForParamError) Error() string {
	return fmt.Sprintf("Expected one value for %s, got %d", e.ParamName, e.Count)
}

// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/api/v1/analytics/churn-chart", wrapper.GetChurnChart)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/analytics/summary", wrapper.GetSummary)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/audit", wrapper.ListAudit)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/auth/config", wrapper.GetAuthConfig)
	m.HandleFunc("POST "+options.BaseURL+"/api/v1/auth/login", wrapper.Login)
	m.HandleFunc("POST "+options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/auth/me", wrapper.GetMe)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/auth/oidc/callback", wrapper.OidcCallback)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/auth/oidc/login", wrapper.OidcLogin)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/customers", wrapper.ListCustomers)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/customers/{id}", wrapper.GetCustomer)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/docs", wrapper.Docs)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/events", wrapper.GetEvents)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/model/settings", wrapper.GetModelSettings)
	m.HandleFunc("PATCH "+options.BaseURL+"/api/v1/model/settings", wrapper.PatchModelSettings)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/openapi.json", wrapper.OpenapiJson)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/openapi.yml", wrapper.OpenapiYaml)
	m.HandleFunc("PATCH "+options.BaseURL+"/api/v1/source/accounts/{id}", wrapper.PatchAccount)
	m.HandleFunc("POST "+options.BaseURL+"/api/v1/source/emulator/actions", wrapper.EmulatorActions)
	m.HandleFunc("POST "+options.BaseURL+"/api/v1/source/emulator/tick", wrapper.EmulatorTick)
	m.HandleFunc("PUT "+options.BaseURL+"/api/v1/source/polling", wrapper.SetSourcePolling)
	m.HandleFunc("PATCH "+options.BaseURL+"/api/v1/source/services/{id}", wrapper.PatchService)
	m.HandleFunc("PUT "+options.BaseURL+"/api/v1/source/snapshot", wrapper.PutSnapshot)
	m.HandleFunc("GET "+options.BaseURL+"/api/v1/source/status", wrapper.GetSourceStatus)
	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Healthz)
	m.HandleFunc("GET "+options.BaseURL+"/metics", wrapper.GetMetricsAlias)
	m.HandleFunc("GET "+options.BaseURL+"/metrics", wrapper.GetMetrics)
	m.HandleFunc("GET "+options.BaseURL+"/ping", wrapper.Ping)
	m.HandleFunc("HEAD "+options.BaseURL+"/ping", wrapper.PingHead)
	m.HandleFunc("GET "+options.BaseURL+"/version", wrapper.Version)

	return m
}

